import * as vscode from 'vscode';

export class ProofCodeCodeActionProvider implements vscode.CodeActionProvider {
  public static readonly providedCodeActionKinds = [vscode.CodeActionKind.QuickFix];

  public provideCodeActions(
    document: vscode.TextDocument,
    _range: vscode.Range | vscode.Selection,
    context: vscode.CodeActionContext,
    _token: vscode.CancellationToken
  ): vscode.CodeAction[] {
    const actions: vscode.CodeAction[] = [];

    // Filter diagnostics generated by ProofCode
    const proofCodeDiagnostics = context.diagnostics.filter(
      (diag) => diag.source === 'ProofCode'
    );

    for (const diag of proofCodeDiagnostics) {
      const lineIdx = diag.range.start.line;
      const line = document.lineAt(lineIdx);
      const lineText = line.text;
      const indentMatch = lineText.match(/^\s*/);
      const indent = indentMatch ? indentMatch[0] : '';

      // 1. Quick Fix for PC-REL-006: Unhandled Async Operation
      if (diag.code === 'PC-REL-006') {
        const action = new vscode.CodeAction(
          '🛡️ ProofCode: Wrap in try/catch block',
          vscode.CodeActionKind.QuickFix
        );
        action.isPreferred = true;
        action.diagnostics = [diag];

        const edit = new vscode.WorkspaceEdit();
        const wrapped = `${indent}try {\n${indent}  ${lineText.trim()}\n${indent}} catch (error) {\n${indent}  console.error('Async operation failed:', error);\n${indent}}`;
        edit.replace(document.uri, line.range, wrapped);
        action.edit = edit;
        actions.push(action);
      }

      // 2. Quick Fix for PC-DATA-001: Unhandled Null/Undefined Database Result
      if (diag.code === 'PC-DATA-001') {
        // Match variable name from diagnostic message or code line
        const varMatch = diag.message.match(/\(([^)]+)\)/);
        const varName = varMatch ? varMatch[1] : 'record';

        // Fix A: Add null guard
        const guardAction = new vscode.CodeAction(
          `🛡️ ProofCode: Add null guard check (if (!${varName}))`,
          vscode.CodeActionKind.QuickFix
        );
        guardAction.isPreferred = true;
        guardAction.diagnostics = [diag];

        const guardEdit = new vscode.WorkspaceEdit();
        const guardText = `${indent}if (!${varName}) throw new Error('${varName} not found');\n`;
        guardEdit.insert(document.uri, new vscode.Position(lineIdx, 0), guardText);
        guardAction.edit = guardEdit;
        actions.push(guardAction);

        // Fix B: Use optional chaining
        const dotIndex = lineText.indexOf(`${varName}.`);
        if (dotIndex !== -1) {
          const optChainAction = new vscode.CodeAction(
            `🛡️ ProofCode: Use optional chaining (${varName}?.${lineText.slice(dotIndex + varName.length + 1).split(/\W/)[0]})`,
            vscode.CodeActionKind.QuickFix
          );
          optChainAction.diagnostics = [diag];

          const optEdit = new vscode.WorkspaceEdit();
          const dotRange = new vscode.Range(
            lineIdx,
            dotIndex + varName.length,
            lineIdx,
            dotIndex + varName.length + 1
          );
          optEdit.replace(document.uri, dotRange, '?.');
          optChainAction.edit = optEdit;
          actions.push(optChainAction);
        }
      }

      // 3. Quick Fix for PC-AUTH-001: Missing Authorization Check in API Route
      if (diag.code === 'PC-AUTH-001') {
        const authAction = new vscode.CodeAction(
          '🛡️ ProofCode: Insert session authentication guard',
          vscode.CodeActionKind.QuickFix
        );
        authAction.isPreferred = true;
        authAction.diagnostics = [diag];

        const authEdit = new vscode.WorkspaceEdit();
        const authSnippet = `${indent}  const session = await auth();\n${indent}  if (!session) return new Response('Unauthorized', { status: 401 });\n`;
        authEdit.insert(document.uri, new vscode.Position(lineIdx + 1, 0), authSnippet);
        authAction.edit = authEdit;
        actions.push(authAction);
      }

      // 4. Quick Fix for PC-SEC-001: Potential SQL Injection
      if (diag.code === 'PC-SEC-001') {
        const sqlAction = new vscode.CodeAction(
          '🛡️ ProofCode: Review query parameterization guidance',
          vscode.CodeActionKind.QuickFix
        );
        sqlAction.diagnostics = [diag];
        actions.push(sqlAction);
      }

      // 5. Quick Fix for PC-REL-008: Unawaited Async Call in Conditional
      if (diag.code === 'PC-REL-008') {
        const awaitAction = new vscode.CodeAction(
          "🛡️ ProofCode: Insert 'await' before async check",
          vscode.CodeActionKind.QuickFix
        );
        awaitAction.isPreferred = true;
        awaitAction.diagnostics = [diag];

        const awaitEdit = new vscode.WorkspaceEdit();
        const replacedLine = lineText.replace(
          /(if\s*\(\s*|while\s*\(\s*|return\s+|\?\s*)([a-zA-Z0-9_$.]+\s*\()/g,
          '$1await $2'
        );
        awaitEdit.replace(document.uri, line.range, replacedLine);
        awaitAction.edit = awaitEdit;
        actions.push(awaitAction);
      }

      // 6. Quick Fix for PC-REL-009: Silent Error Swallowing in Catch Block
      if (diag.code === 'PC-REL-009') {
        const logAction = new vscode.CodeAction(
          '🛡️ ProofCode: Add logger to catch block',
          vscode.CodeActionKind.QuickFix
        );
        logAction.isPreferred = true;
        logAction.diagnostics = [diag];

        const logEdit = new vscode.WorkspaceEdit();
        const loggedCatch = lineText.includes('catch')
          ? lineText.replace(
              /catch\s*(\([^)]*\))?\s*\{[^}]*\}/,
              (m) => {
                const errParam = m.includes('(') ? m.match(/\(([^)]+)\)/)?.[1] || 'error' : 'error';
                return `catch (${errParam}) {\n${indent}  console.error('Operation failed:', ${errParam});\n${indent}}`;
              }
            )
          : `${indent}  console.error('Operation failed:', error);`;
        logEdit.replace(document.uri, line.range, loggedCatch);
        logAction.edit = logEdit;
        actions.push(logAction);
      }

      // 7. Quick Fix for PC-SEC-003: Path Traversal
      if (diag.code === 'PC-SEC-003') {
        const sanitizeAction = new vscode.CodeAction(
          '🛡️ ProofCode: Sanitize file path with path.basename()',
          vscode.CodeActionKind.QuickFix
        );
        sanitizeAction.isPreferred = true;
        sanitizeAction.diagnostics = [diag];
        actions.push(sanitizeAction);
      }

      // 8. Quick Fix for PC-TYPE-001: Dangerous Type Assertion Bypass
      if (diag.code === 'PC-TYPE-001') {
        if (lineText.includes('as any')) {
          const typeAction = new vscode.CodeAction(
            "🛡️ ProofCode: Replace unsafe 'as any' with 'as unknown'",
            vscode.CodeActionKind.QuickFix
          );
          typeAction.isPreferred = true;
          typeAction.diagnostics = [diag];

          const typeEdit = new vscode.WorkspaceEdit();
          const replaced = lineText.replace(/\bas\s+any\b/g, 'as unknown');
          typeEdit.replace(document.uri, line.range, replaced);
          typeAction.edit = typeEdit;
          actions.push(typeAction);
        } else if (/\/\/\s*@ts-(ignore|nocheck|expect-error)\b/.test(lineText)) {
          const removeSuppressionAction = new vscode.CodeAction(
            '🛡️ ProofCode: Remove TypeScript suppression directive',
            vscode.CodeActionKind.QuickFix
          );
          removeSuppressionAction.isPreferred = true;
          removeSuppressionAction.diagnostics = [diag];

          const supEdit = new vscode.WorkspaceEdit();
          // Delete entire line if it only contains the comment, else remove comment
          if (/^\s*\/\/\s*@ts-(ignore|nocheck|expect-error)\b[^\n]*$/.test(lineText)) {
            supEdit.delete(
              document.uri,
              new vscode.Range(lineIdx, 0, Math.min(document.lineCount - 1, lineIdx + 1), 0)
            );
          } else {
            const stripped = lineText.replace(/\/\/\s*@ts-(ignore|nocheck|expect-error)\b[^\n]*/, '').trimEnd();
            supEdit.replace(document.uri, line.range, stripped);
          }
          removeSuppressionAction.edit = supEdit;
          actions.push(removeSuppressionAction);
        }
      }

      // 9. Quick Fix for PC-IMPORT-001: Phantom / Hallucinated Dependency
      if (diag.code === 'PC-IMPORT-001') {
        const removeImportAction = new vscode.CodeAction(
          '🛡️ ProofCode: Remove uninstalled/phantom import statement',
          vscode.CodeActionKind.QuickFix
        );
        removeImportAction.isPreferred = true;
        removeImportAction.diagnostics = [diag];

        const importEdit = new vscode.WorkspaceEdit();
        importEdit.delete(
          document.uri,
          new vscode.Range(lineIdx, 0, Math.min(document.lineCount - 1, lineIdx + 1), 0)
        );
        removeImportAction.edit = importEdit;
        actions.push(removeImportAction);
      }
    }

    return actions;
  }
}
